import React, { useState, useEffect } from 'react';
import { 
  ChevronLeft, 
  ChevronRight, 
  Calendar as CalendarIcon, 
  Plus,
  MoreHorizontal,
  Clock,
  Users,
  Package
} from 'lucide-react';
import eventBus, { EVENTS } from '../services/eventBus';

const ModernCalendar = ({ selectedPeriod, onPeriodChange, onDateSelect, assignments = [] }) => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [viewMonth, setViewMonth] = useState(new Date().getMonth());
  const [viewYear, setViewYear] = useState(new Date().getFullYear());
  const [selectedDate, setSelectedDate] = useState(null);
  const [viewMode, setViewMode] = useState('month'); // month, week, day
  const [showEventForm, setShowEventForm] = useState(false);
  const [selectedDayForEvent, setSelectedDayForEvent] = useState(null);
  const [newEvent, setNewEvent] = useState({
    materialId: '',
    quantity: '',
    assignedTo: ''
  });
  
  // Custom events state
  const [customEvents, setCustomEvents] = useState([]);
  const [showCustomEventForm, setShowCustomEventForm] = useState(false);
  const [newCustomEvent, setNewCustomEvent] = useState({
    title: '',
    description: '',
    color: '#3b82f6', // Default blue color
    date: null
  });
  
  // Available colors for events
  const eventColors = [
    { name: 'Plava', value: '#3b82f6' },
    { name: 'Zelena', value: '#10b981' },
    { name: 'Žuta', value: '#f59e0b' },
    { name: 'Crvena', value: '#dc2626' },
    { name: 'Ljubičasta', value: '#8b5cf6' },
    { name: 'Roze', value: '#ec4899' },
    { name: 'Indigo', value: '#6366f1' },
    { name: 'Teal', value: '#14b8a6' },
    { name: 'Orange', value: '#f97316' },
    { name: 'Siva', value: '#6b7280' }
  ];

  // Mesec nazivi na srpskom
  const monthNames = [
    'Januar', 'Februar', 'Mart', 'April', 'Maj', 'Jun',
    'Jul', 'Avgust', 'Septembar', 'Oktobar', 'Novembar', 'Decembar'
  ];

  // Dan nazivi na srpskom
  const dayNames = ['Nedelja', 'Ponedeljak', 'Utorak', 'Sreda', 'Četvrtak', 'Petak', 'Subota'];
  const shortDayNames = ['Ned', 'Pon', 'Uto', 'Sre', 'Čet', 'Pet', 'Sub'];

  // Generiši kalendar za trenutni mesec
  const generateCalendar = (month, year) => {
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    const startDate = new Date(firstDay);
    startDate.setDate(startDate.getDate() - firstDay.getDay());

    const calendar = [];
    const currentDate = new Date(startDate);
    const today = new Date();

    if (viewMode === 'week') {
      // Nedeljni pregled - prikaži samo trenutnu nedelju
      const currentWeekStart = new Date(today);
      currentWeekStart.setDate(today.getDate() - today.getDay());
      
      const weekDays = [];
      for (let day = 0; day < 7; day++) {
        const date = new Date(currentWeekStart);
        date.setDate(currentWeekStart.getDate() + day);
        
        const isCurrentMonth = date.getMonth() === month;
        const isToday = date.toDateString() === today.toDateString();
        const isSelected = selectedDate && date.toDateString() === selectedDate.toDateString();
        const isInSelectedPeriod = selectedPeriod &&
          date >= selectedPeriod.from &&
          date <= selectedPeriod.to;

        const dayEvents = getEventsForDate(date);

        weekDays.push({
          date,
          day: date.getDate(),
          isCurrentMonth,
          isToday,
          isSelected,
          isInSelectedPeriod,
          events: dayEvents
        });
      }
      calendar.push(weekDays);
    } else if (viewMode === 'day') {
      // Dnevni pregled - prikaži samo trenutni dan
      const dayEvents = getEventsForDate(today);
      const weekDays = [{
        date: today,
        day: today.getDate(),
        isCurrentMonth: today.getMonth() === month,
        isToday: true,
        isSelected: selectedDate && today.toDateString() === selectedDate.toDateString(),
        isInSelectedPeriod: selectedPeriod &&
          today >= selectedPeriod.from &&
          today <= selectedPeriod.to,
        events: dayEvents
      }];
      calendar.push(weekDays);
    } else {
      // Mesečni pregled - prikaži sve nedelje
      for (let week = 0; week < 6; week++) {
        const weekDays = [];
        for (let day = 0; day < 7; day++) {
          const date = new Date(currentDate);
          const isCurrentMonth = date.getMonth() === month;
          const isToday = date.toDateString() === today.toDateString();
          const isSelected = selectedDate && date.toDateString() === selectedDate.toDateString();
          const isInSelectedPeriod = selectedPeriod &&
            date >= selectedPeriod.from &&
            date <= selectedPeriod.to;

          const dayEvents = getEventsForDate(date);

          weekDays.push({
            date,
            day: date.getDate(),
            isCurrentMonth,
            isToday,
            isSelected,
            isInSelectedPeriod,
            events: dayEvents
          });

          currentDate.setDate(currentDate.getDate() + 1);
        }
        calendar.push(weekDays);
      }
    }

    return calendar;
  };

  // Dohvati događaje za određeni dan
  const getEventsForDate = (date) => {
    const events = [];
    
    // Material events
    if (assignments && assignments.length > 0) {
      // Formatiraj datum u format 'DD.MM.'
      const day = date.getDate().toString().padStart(2, '0');
      const month = (date.getMonth() + 1).toString().padStart(2, '0');
      const dateKey = `${day}.${month}.`;
      
      assignments.forEach(material => {
        if (material.quantities && material.quantities[dateKey] && material.quantities[dateKey] > 0) {
          events.push({
            id: `material-${material.id}`,
            name: material.name,
            category: material.category,
            department: material.department,
            assignedTo: material.assignedTo,
            quantity: material.quantities[dateKey],
            unit: 'kom',
            type: 'material',
            color: '#dc2626' // Red color for materials
          });
        }
      });
    }
    
    // Custom events
    const dateStr = date.toDateString();
    customEvents.forEach(event => {
      if (event.date && event.date.toDateString() === dateStr) {
        events.push({
          id: `custom-${event.id}`,
          name: event.title,
          description: event.description,
          type: 'custom',
          color: event.color
        });
      }
    });
    
    return events;
  };

  // Navigacija
  const goToPreviousMonth = () => {
    if (viewMode === 'week') {
      // Nedeljni pregled - idi na prethodnu nedelju
      const currentWeekStart = new Date(viewYear, viewMonth, 1);
      currentWeekStart.setDate(currentWeekStart.getDate() - currentWeekStart.getDay());
      currentWeekStart.setDate(currentWeekStart.getDate() - 7);
      setViewMonth(currentWeekStart.getMonth());
      setViewYear(currentWeekStart.getFullYear());
    } else if (viewMode === 'day') {
      // Dnevni pregled - idi na prethodni dan
      const currentDay = new Date(viewYear, viewMonth, 1);
      currentDay.setDate(currentDay.getDate() - 1);
      setViewMonth(currentDay.getMonth());
      setViewYear(currentDay.getFullYear());
    } else {
      // Mesečni pregled
      if (viewMonth === 0) {
        setViewMonth(11);
        setViewYear(viewYear - 1);
      } else {
        setViewMonth(viewMonth - 1);
      }
    }
  };

  const goToNextMonth = () => {
    if (viewMode === 'week') {
      // Nedeljni pregled - idi na sledeću nedelju
      const currentWeekStart = new Date(viewYear, viewMonth, 1);
      currentWeekStart.setDate(currentWeekStart.getDate() - currentWeekStart.getDay());
      currentWeekStart.setDate(currentWeekStart.getDate() + 7);
      setViewMonth(currentWeekStart.getMonth());
      setViewYear(currentWeekStart.getFullYear());
    } else if (viewMode === 'day') {
      // Dnevni pregled - idi na sledeći dan
      const currentDay = new Date(viewYear, viewMonth, 1);
      currentDay.setDate(currentDay.getDate() + 1);
      setViewMonth(currentDay.getMonth());
      setViewYear(currentDay.getFullYear());
    } else {
      // Mesečni pregled
      if (viewMonth === 11) {
        setViewMonth(0);
        setViewYear(viewYear + 1);
      } else {
        setViewMonth(viewMonth + 1);
      }
    }
  };

  const goToCurrentMonth = () => {
    const now = new Date();
    setViewMonth(now.getMonth());
    setViewYear(now.getFullYear());
    setCurrentDate(now);
  };

  // Izbor datuma
  const handleDateClick = (dateInfo) => {
    setSelectedDate(dateInfo.date);

    // Kreiraj period za izabrani mesec
    const period = {
      from: new Date(dateInfo.date.getFullYear(), dateInfo.date.getMonth(), 1),
      to: new Date(dateInfo.date.getFullYear(), dateInfo.date.getMonth() + 1, 0),
      label: `${monthNames[dateInfo.date.getMonth()]} ${dateInfo.date.getFullYear()}`
    };

    onPeriodChange(period);

    if (onDateSelect) {
      onDateSelect(dateInfo.date);
    }
  };

  // Dupli klik za dodavanje eventa
  const handleDateDoubleClick = (dateInfo) => {
    setSelectedDayForEvent(dateInfo.date);
    setShowEventForm(true);
  };

  // Dodaj novi događaj
  const handleAddEvent = () => {
    if (!newEvent.materialId || !newEvent.quantity || !selectedDayForEvent) return;
    
    // Formatiraj datum u format 'DD.MM.'
    const day = selectedDayForEvent.getDate().toString().padStart(2, '0');
    const month = (selectedDayForEvent.getMonth() + 1).toString().padStart(2, '0');
    const dateKey = `${day}.${month}.`;
    
    // Pronađi materijal
    const material = assignments.find(m => m.id === parseInt(newEvent.materialId));
    if (material) {
      // Ažuriraj quantities
      const updatedMaterial = {
        ...material,
        quantities: {
          ...material.quantities,
          [dateKey]: parseInt(newEvent.quantity)
        }
      };
      
      // Emituj evente za ažuriranje
      if (window.eventBus) {
        window.eventBus.emit('MATERIAL_UPDATED', updatedMaterial);
      }
      
      // Emituj evente za admin panel
      eventBus.emit(EVENTS.MATERIAL_UPDATED, { material: updatedMaterial });
      eventBus.emit(EVENTS.ASSIGNMENT_CREATED, { assignment: { material: updatedMaterial, quantity: parseInt(newEvent.quantity), date: selectedDayForEvent } });
      eventBus.emit(EVENTS.INVENTORY_UPDATED, { material: updatedMaterial });
      eventBus.emit(EVENTS.DATA_SYNC_NEEDED, { type: 'material_assignment_created', data: { material: updatedMaterial, quantity: parseInt(newEvent.quantity), date: selectedDayForEvent } });
      
      // Resetuj formu
      setNewEvent({ materialId: '', quantity: '', assignedTo: '' });
      setShowEventForm(false);
      setSelectedDayForEvent(null);
    }
  };

  // Dodaj custom događaj
  const handleAddCustomEvent = () => {
    if (!newCustomEvent.title || !newCustomEvent.date) return;
    
    const customEvent = {
      id: Date.now(),
      title: newCustomEvent.title,
      description: newCustomEvent.description,
      color: newCustomEvent.color,
      date: new Date(newCustomEvent.date)
    };
    
    setCustomEvents(prev => [...prev, customEvent]);
    
    // Emituj evente za admin panel
    eventBus.emit(EVENTS.DATA_SYNC_NEEDED, { type: 'custom_event_created', data: customEvent });
    
    // Resetuj formu
    setNewCustomEvent({
      title: '',
      description: '',
      color: '#3b82f6',
      date: null
    });
    setShowCustomEventForm(false);
  };

  // Obriši custom događaj
  const handleDeleteCustomEvent = (eventId) => {
    console.log('Brisanje custom događaja sa ID:', eventId);
    console.log('Trenutni custom događaji:', customEvents);
    
    const eventToDelete = customEvents.find(event => event.id === eventId);
    
    setCustomEvents(prev => {
      const filtered = prev.filter(event => event.id !== eventId);
      console.log('Filtrirani događaji:', filtered);
      return filtered;
    });
    
    // Emituj event za admin panel
    if (eventToDelete) {
      eventBus.emit(EVENTS.DATA_SYNC_NEEDED, { type: 'custom_event_deleted', data: eventToDelete });
    }
  };

  // Ažuriraj viewMonth i viewYear kada se promeni selectedPeriod
  useEffect(() => {
    if (selectedPeriod) {
      setViewMonth(selectedPeriod.from.getMonth());
      setViewYear(selectedPeriod.from.getFullYear());
    }
  }, [selectedPeriod]);

  const calendar = generateCalendar(viewMonth, viewYear);

  return (
    <div style={{
      backgroundColor: '#1f2937',
      borderRadius: '16px',
      padding: '2rem',
      border: '2px solid #374151',
      boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04)'
    }}>
      {/* Header */}
      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        marginBottom: '2rem',
        paddingBottom: '1rem',
        borderBottom: '2px solid #374151'
      }}>
        {/* Naslov */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
          <CalendarIcon size={32} color="#dc2626" />
          <div>
            <h2 style={{ 
              color: '#ffffff', 
              fontSize: '1.875rem', 
              fontWeight: '700', 
              margin: 0 
            }}>
              {viewMode === 'month' && `${monthNames[viewMonth]} ${viewYear}`}
              {viewMode === 'week' && `Nedelja ${viewMonth + 1}. ${viewYear}`}
              {viewMode === 'day' && `${dayNames[new Date(viewYear, viewMonth, 1).getDay()]}, ${1}. ${monthNames[viewMonth]} ${viewYear}`}
            </h2>
            <p style={{ 
              color: '#9ca3af', 
              fontSize: '0.875rem', 
              margin: 0 
            }}>
              {viewMode === 'month' && 'Mesečni pregled izdavanja materijala'}
              {viewMode === 'week' && 'Nedeljni pregled izdavanja materijala'}
              {viewMode === 'day' && 'Dnevni pregled izdavanja materijala'}
            </p>
          </div>
        </div>

        {/* Kontrole */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
          {/* Dodaj događaj dugmad */}
          <div style={{ display: 'flex', gap: '0.5rem' }}>
            <button
              onClick={() => {
                setSelectedDayForEvent(new Date());
                setShowEventForm(true);
              }}
              style={{
                padding: '0.75rem 1.5rem',
                backgroundColor: '#dc2626',
                border: 'none',
                borderRadius: '8px',
                color: '#ffffff',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: '0.5rem',
                fontSize: '0.875rem',
                fontWeight: '600',
                transition: 'all 0.2s'
              }}
              onMouseEnter={(e) => {
                e.target.style.backgroundColor = '#b91c1c';
              }}
              onMouseLeave={(e) => {
                e.target.style.backgroundColor = '#dc2626';
              }}
            >
              <Plus size={16} />
              Dodaj izdavanje
            </button>
            
            <button
              onClick={() => {
                setNewCustomEvent(prev => ({ ...prev, date: new Date() }));
                setShowCustomEventForm(true);
              }}
              style={{
                padding: '0.75rem 1.5rem',
                backgroundColor: '#3b82f6',
                border: 'none',
                borderRadius: '8px',
                color: '#ffffff',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: '0.5rem',
                fontSize: '0.875rem',
                fontWeight: '600',
                transition: 'all 0.2s'
              }}
              onMouseEnter={(e) => {
                e.target.style.backgroundColor = '#2563eb';
              }}
              onMouseLeave={(e) => {
                e.target.style.backgroundColor = '#3b82f6';
              }}
            >
              <Plus size={16} />
              Dodaj događaj
            </button>
          </div>

          {/* View Mode Toggle */}
          <div style={{
            display: 'flex',
            backgroundColor: '#374151',
            borderRadius: '8px',
            padding: '4px'
          }}>
            {['month', 'week', 'day'].map((mode) => (
              <button
                key={mode}
                onClick={() => setViewMode(mode)}
                style={{
                  padding: '0.5rem 1rem',
                  borderRadius: '6px',
                  border: 'none',
                  backgroundColor: viewMode === mode ? '#dc2626' : 'transparent',
                  color: viewMode === mode ? '#ffffff' : '#9ca3af',
                  fontSize: '0.875rem',
                  fontWeight: '600',
                  cursor: 'pointer',
                  transition: 'all 0.2s'
                }}
              >
                {mode === 'month' ? 'Mesec' : mode === 'week' ? 'Nedelja' : 'Dan'}
              </button>
            ))}
          </div>

          {/* Navigacija */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <button
              onClick={goToPreviousMonth}
              style={{
                padding: '0.75rem',
                backgroundColor: '#374151',
                border: 'none',
                borderRadius: '8px',
                color: '#d1d5db',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                transition: 'all 0.2s'
              }}
              onMouseEnter={(e) => {
                e.target.style.backgroundColor = '#4b5563';
              }}
              onMouseLeave={(e) => {
                e.target.style.backgroundColor = '#374151';
              }}
            >
              <ChevronLeft size={20} />
            </button>

            <button
              onClick={goToCurrentMonth}
              style={{
                padding: '0.75rem 1.5rem',
                backgroundColor: '#dc2626',
                border: 'none',
                borderRadius: '8px',
                color: '#ffffff',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: '0.5rem',
                fontSize: '0.875rem',
                fontWeight: '600',
                transition: 'all 0.2s'
              }}
              onMouseEnter={(e) => {
                e.target.style.backgroundColor = '#b91c1c';
              }}
              onMouseLeave={(e) => {
                e.target.style.backgroundColor = '#dc2626';
              }}
            >
              <CalendarIcon size={16} />
              Danas
            </button>

            <button
              onClick={goToNextMonth}
              style={{
                padding: '0.75rem',
                backgroundColor: '#374151',
                border: 'none',
                borderRadius: '8px',
                color: '#d1d5db',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                transition: 'all 0.2s'
              }}
              onMouseEnter={(e) => {
                e.target.style.backgroundColor = '#4b5563';
              }}
              onMouseLeave={(e) => {
                e.target.style.backgroundColor = '#374151';
              }}
            >
              <ChevronRight size={20} />
            </button>
          </div>
        </div>
      </div>

      {/* Kalendar Grid */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: viewMode === 'day' ? '1fr' : 'repeat(7, 1fr)',
        gap: '1px',
        backgroundColor: '#4b5563',
        borderRadius: '12px',
        overflow: 'hidden'
      }}>
        {/* Dan nazivi */}
        {(viewMode === 'day' ? [shortDayNames[new Date().getDay()]] : shortDayNames).map((day, index) => (
          <div
            key={day}
            style={{
              backgroundColor: '#374151',
              padding: '1rem',
              textAlign: 'center',
              color: '#9ca3af',
              fontSize: '0.875rem',
              fontWeight: '600',
              textTransform: 'uppercase',
              letterSpacing: '0.05em'
            }}
          >
            {day}
          </div>
        ))}

        {/* Kalendar dana */}
        {calendar.map((week, weekIndex) =>
          week.map((dayInfo, dayIndex) => (
            <button
              key={`${weekIndex}-${dayIndex}`}
              onClick={() => handleDateClick(dayInfo)}
              onDoubleClick={() => handleDateDoubleClick(dayInfo)}
              style={{
                backgroundColor: dayInfo.isCurrentMonth ? '#1f2937' : '#111827',
                border: 'none',
                padding: '1rem',
                minHeight: viewMode === 'day' ? '400px' : '120px',
                cursor: 'pointer',
                position: 'relative',
                transition: 'all 0.2s',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'flex-start',
                textAlign: 'left'
              }}
              onMouseEnter={(e) => {
                if (dayInfo.isCurrentMonth) {
                  e.target.style.backgroundColor = '#374151';
                }
              }}
              onMouseLeave={(e) => {
                if (dayInfo.isCurrentMonth) {
                  e.target.style.backgroundColor = '#1f2937';
                }
              }}
            >
              {/* Dan broj */}
              <div style={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                width: '100%',
                marginBottom: '0.5rem'
              }}>
                <span style={{
                  color: dayInfo.isCurrentMonth 
                    ? (dayInfo.isToday ? '#dc2626' : '#ffffff')
                    : '#6b7280',
                  fontSize: '1rem',
                  fontWeight: dayInfo.isToday ? '700' : '500',
                  backgroundColor: dayInfo.isToday ? '#fef2f2' : 'transparent',
                  borderRadius: '50%',
                  width: '32px',
                  height: '32px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center'
                }}>
                  {dayInfo.day}
                </span>
                
                {/* Event indicator */}
                {dayInfo.events.length > 0 && (
                  <div style={{
                    backgroundColor: '#dc2626',
                    borderRadius: '50%',
                    width: '8px',
                    height: '8px'
                  }} />
                )}
              </div>

              {/* Eventi */}
              <div style={{ width: '100%', flex: 1 }}>
                {dayInfo.events.slice(0, 3).map((event, eventIndex) => (
                  <div
                    key={eventIndex}
                    style={{
                      backgroundColor: event.color,
                      color: '#ffffff',
                      padding: '0.25rem 0.5rem',
                      borderRadius: '4px',
                      fontSize: '0.75rem',
                      marginBottom: '0.25rem',
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      whiteSpace: 'nowrap',
                      border: event.type === 'custom' ? '1px solid rgba(255,255,255,0.3)' : 'none'
                    }}
                    title={event.type === 'material' 
                      ? `${event.name} - ${event.quantity} ${event.unit}` 
                      : event.description || event.name
                    }
                  >
                    {event.name}
                  </div>
                ))}
                {dayInfo.events.length > 3 && (
                  <div style={{
                    color: '#9ca3af',
                    fontSize: '0.75rem',
                    fontStyle: 'italic'
                  }}>
                    +{dayInfo.events.length - 3} više
                  </div>
                )}
              </div>
            </button>
          ))
        )}
      </div>

      {/* Selected Date Info */}
      {selectedDate && (
        <div style={{
          marginTop: '2rem',
          padding: '1.5rem',
          backgroundColor: '#374151',
          borderRadius: '12px',
          border: '2px solid #dc2626'
        }}>
          <h3 style={{ 
            color: '#ffffff', 
            fontSize: '1.25rem', 
            fontWeight: '600', 
            margin: '0 0 1rem 0' 
          }}>
            {dayNames[selectedDate.getDay()]}, {selectedDate.getDate()}. {monthNames[selectedDate.getMonth()]} {selectedDate.getFullYear()}
          </h3>
          
          {getEventsForDate(selectedDate).length > 0 ? (
            <div>
              <p style={{ color: '#9ca3af', marginBottom: '1rem' }}>
                {getEventsForDate(selectedDate).length} događaja
              </p>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                {getEventsForDate(selectedDate).map((event, index) => (
                  <div
                    key={index}
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      gap: '0.75rem',
                      padding: '0.75rem',
                      backgroundColor: '#1f2937',
                      borderRadius: '8px',
                      border: '1px solid #4b5563',
                      position: 'relative'
                    }}
                  >
                    <div style={{
                      backgroundColor: event.color,
                      borderRadius: '50%',
                      width: '12px',
                      height: '12px'
                    }} />
                    <div style={{ flex: 1 }}>
                      <p style={{ 
                        color: '#ffffff', 
                        margin: 0, 
                        fontSize: '0.875rem',
                        fontWeight: '500'
                      }}>
                        {event.name}
                      </p>
                      <p style={{ 
                        color: '#9ca3af', 
                        margin: 0, 
                        fontSize: '0.75rem'
                      }}>
                        {event.type === 'material' 
                          ? `${event.assignedTo} • ${event.quantity} ${event.unit} • ${event.department}`
                          : event.description || 'Custom događaj'
                        }
                      </p>
                    </div>
                    {event.type === 'custom' && (
                      <button
                        onClick={() => {
                          const eventId = parseInt(event.id.replace('custom-', ''));
                          handleDeleteCustomEvent(eventId);
                        }}
                        style={{
                          background: 'none',
                          border: 'none',
                          color: '#ef4444',
                          cursor: 'pointer',
                          padding: '0.25rem',
                          borderRadius: '4px',
                          fontSize: '0.75rem'
                        }}
                        title="Obriši događaj"
                      >
                        ×
                      </button>
                    )}
                  </div>
                ))}
              </div>
            </div>
          ) : (
            <p style={{ color: '#9ca3af', margin: 0 }}>
              Nema događaja za ovaj dan
            </p>
          )}
        </div>
      )}

      {/* Forma za dodavanje događaja */}
      {showEventForm && selectedDayForEvent && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundColor: 'rgba(0, 0, 0, 0.8)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 1000
        }}>
          <div style={{
            backgroundColor: '#1f2937',
            borderRadius: '16px',
            padding: '2rem',
            border: '2px solid #374151',
            minWidth: '400px',
            maxWidth: '500px'
          }}>
            <h3 style={{ 
              color: '#ffffff', 
              fontSize: '1.5rem', 
              fontWeight: '600', 
              margin: '0 0 1rem 0' 
            }}>
              Dodaj izdavanje materijala
            </h3>
            
            <p style={{ 
              color: '#9ca3af', 
              margin: '0 0 1.5rem 0',
              fontSize: '0.875rem'
            }}>
              {dayNames[selectedDayForEvent.getDay()]}, {selectedDayForEvent.getDate()}. {monthNames[selectedDayForEvent.getMonth()]} {selectedDayForEvent.getFullYear()}
            </p>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
              {/* Materijal dropdown */}
              <div>
                <label style={{ 
                  display: 'block', 
                  color: '#d1d5db', 
                  fontSize: '0.875rem', 
                  fontWeight: '500',
                  marginBottom: '0.5rem'
                }}>
                  Materijal *
                </label>
                <select
                  value={newEvent.materialId}
                  onChange={(e) => setNewEvent(prev => ({ ...prev, materialId: e.target.value }))}
                  style={{
                    width: '100%',
                    padding: '0.75rem',
                    backgroundColor: '#374151',
                    border: '2px solid #4b5563',
                    borderRadius: '8px',
                    color: '#d1d5db',
                    fontSize: '0.875rem'
                  }}
                >
                  <option value="">Izaberi materijal...</option>
                  {assignments.map(material => (
                    <option key={material.id} value={material.id}>
                      {material.name} ({material.category})
                    </option>
                  ))}
                </select>
              </div>

              {/* Količina */}
              <div>
                <label style={{ 
                  display: 'block', 
                  color: '#d1d5db', 
                  fontSize: '0.875rem', 
                  fontWeight: '500',
                  marginBottom: '0.5rem'
                }}>
                  Količina *
                </label>
                <input
                  type="number"
                  value={newEvent.quantity}
                  onChange={(e) => setNewEvent(prev => ({ ...prev, quantity: e.target.value }))}
                  placeholder="Unesite količinu..."
                  min="1"
                  style={{
                    width: '100%',
                    padding: '0.75rem',
                    backgroundColor: '#374151',
                    border: '2px solid #4b5563',
                    borderRadius: '8px',
                    color: '#d1d5db',
                    fontSize: '0.875rem'
                  }}
                />
              </div>

              {/* Dugmad */}
              <div style={{ 
                display: 'flex', 
                gap: '1rem', 
                justifyContent: 'flex-end',
                marginTop: '1rem'
              }}>
                <button
                  onClick={() => {
                    setShowEventForm(false);
                    setSelectedDayForEvent(null);
                    setNewEvent({ materialId: '', quantity: '', assignedTo: '' });
                  }}
                  style={{
                    padding: '0.75rem 1.5rem',
                    backgroundColor: '#374151',
                    border: 'none',
                    borderRadius: '8px',
                    color: '#d1d5db',
                    cursor: 'pointer',
                    fontSize: '0.875rem',
                    fontWeight: '500'
                  }}
                >
                  Otkaži
                </button>
                <button
                  onClick={handleAddEvent}
                  disabled={!newEvent.materialId || !newEvent.quantity}
                  style={{
                    padding: '0.75rem 1.5rem',
                    backgroundColor: newEvent.materialId && newEvent.quantity ? '#dc2626' : '#6b7280',
                    border: 'none',
                    borderRadius: '8px',
                    color: '#ffffff',
                    cursor: newEvent.materialId && newEvent.quantity ? 'pointer' : 'not-allowed',
                    fontSize: '0.875rem',
                    fontWeight: '500'
                  }}
                >
                  Dodaj
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Forma za dodavanje custom događaja */}
      {showCustomEventForm && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundColor: 'rgba(0, 0, 0, 0.8)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 1000
        }}>
          <div style={{
            backgroundColor: '#1f2937',
            borderRadius: '16px',
            padding: '2rem',
            border: '2px solid #374151',
            minWidth: '400px',
            maxWidth: '500px'
          }}>
            <h3 style={{ 
              color: '#ffffff', 
              fontSize: '1.5rem', 
              fontWeight: '600', 
              margin: '0 0 1rem 0' 
            }}>
              Dodaj custom događaj
            </h3>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
              {/* Naslov događaja */}
              <div>
                <label style={{ 
                  display: 'block', 
                  color: '#d1d5db', 
                  fontSize: '0.875rem', 
                  fontWeight: '500',
                  marginBottom: '0.5rem'
                }}>
                  Naslov događaja *
                </label>
                <input
                  type="text"
                  value={newCustomEvent.title}
                  onChange={(e) => setNewCustomEvent(prev => ({ ...prev, title: e.target.value }))}
                  placeholder="Unesite naslov događaja..."
                  style={{
                    width: '100%',
                    padding: '0.75rem',
                    backgroundColor: '#374151',
                    border: '2px solid #4b5563',
                    borderRadius: '8px',
                    color: '#d1d5db',
                    fontSize: '0.875rem'
                  }}
                />
              </div>

              {/* Opis događaja */}
              <div>
                <label style={{ 
                  display: 'block', 
                  color: '#d1d5db', 
                  fontSize: '0.875rem', 
                  fontWeight: '500',
                  marginBottom: '0.5rem'
                }}>
                  Opis (opciono)
                </label>
                <textarea
                  value={newCustomEvent.description}
                  onChange={(e) => setNewCustomEvent(prev => ({ ...prev, description: e.target.value }))}
                  placeholder="Unesite opis događaja..."
                  rows={3}
                  style={{
                    width: '100%',
                    padding: '0.75rem',
                    backgroundColor: '#374151',
                    border: '2px solid #4b5563',
                    borderRadius: '8px',
                    color: '#d1d5db',
                    fontSize: '0.875rem',
                    resize: 'vertical'
                  }}
                />
              </div>

              {/* Datum */}
              <div>
                <label style={{ 
                  display: 'block', 
                  color: '#d1d5db', 
                  fontSize: '0.875rem', 
                  fontWeight: '500',
                  marginBottom: '0.5rem'
                }}>
                  Datum *
                </label>
                <input
                  type="date"
                  value={newCustomEvent.date ? newCustomEvent.date.toISOString().split('T')[0] : ''}
                  onChange={(e) => setNewCustomEvent(prev => ({ 
                    ...prev, 
                    date: e.target.value ? new Date(e.target.value) : null 
                  }))}
                  style={{
                    width: '100%',
                    padding: '0.75rem',
                    backgroundColor: '#374151',
                    border: '2px solid #4b5563',
                    borderRadius: '8px',
                    color: '#d1d5db',
                    fontSize: '0.875rem'
                  }}
                />
              </div>

              {/* Color picker */}
              <div>
                <label style={{ 
                  display: 'block', 
                  color: '#d1d5db', 
                  fontSize: '0.875rem', 
                  fontWeight: '500',
                  marginBottom: '0.5rem'
                }}>
                  Boja događaja
                </label>
                <div style={{ 
                  display: 'grid', 
                  gridTemplateColumns: 'repeat(5, 1fr)', 
                  gap: '0.5rem' 
                }}>
                  {eventColors.map((color) => (
                    <button
                      key={color.value}
                      onClick={() => setNewCustomEvent(prev => ({ ...prev, color: color.value }))}
                      style={{
                        width: '100%',
                        height: '40px',
                        backgroundColor: color.value,
                        border: newCustomEvent.color === color.value ? '3px solid #ffffff' : '2px solid #4b5563',
                        borderRadius: '8px',
                        cursor: 'pointer',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        fontSize: '0.75rem',
                        fontWeight: '600',
                        color: '#ffffff',
                        textShadow: '1px 1px 2px rgba(0,0,0,0.7)'
                      }}
                      title={color.name}
                    >
                      {newCustomEvent.color === color.value && '✓'}
                    </button>
                  ))}
                </div>
              </div>

              {/* Dugmad */}
              <div style={{ 
                display: 'flex', 
                gap: '1rem', 
                justifyContent: 'flex-end',
                marginTop: '1rem'
              }}>
                <button
                  onClick={() => {
                    setShowCustomEventForm(false);
                    setNewCustomEvent({
                      title: '',
                      description: '',
                      color: '#3b82f6',
                      date: null
                    });
                  }}
                  style={{
                    padding: '0.75rem 1.5rem',
                    backgroundColor: '#374151',
                    border: 'none',
                    borderRadius: '8px',
                    color: '#d1d5db',
                    cursor: 'pointer',
                    fontSize: '0.875rem',
                    fontWeight: '500'
                  }}
                >
                  Otkaži
                </button>
                <button
                  onClick={handleAddCustomEvent}
                  disabled={!newCustomEvent.title || !newCustomEvent.date}
                  style={{
                    padding: '0.75rem 1.5rem',
                    backgroundColor: newCustomEvent.title && newCustomEvent.date ? '#3b82f6' : '#6b7280',
                    border: 'none',
                    borderRadius: '8px',
                    color: '#ffffff',
                    cursor: newCustomEvent.title && newCustomEvent.date ? 'pointer' : 'not-allowed',
                    fontSize: '0.875rem',
                    fontWeight: '500'
                  }}
                >
                  Dodaj
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ModernCalendar;
